    public static string Get(string? key)
    {
        if (string.IsNullOrWhiteSpace(key)) return "";
        if (Entries.TryGetValue(key.Trim(), out var answer)) return answer;
        foreach (var entry in Entries)
            if (key.Contains(entry.Key, StringComparison.OrdinalIgnoreCase)) return entry.Value;
        return "Наведите на обозначение или откройте вкладку «Подсказки и формулы». Для расчётов реальных АУПТ обязательна проверка инженером.";
    }

    public static IReadOnlyList<KeyValuePair<string,string>> All =>
        new List<KeyValuePair<string,string>>(Entries).AsReadOnly();
}

public sealed class HelpTooltipConverter : IValueConverter
{
    public object Convert(object value, Type targetType, object parameter, CultureInfo culture) =>
        HelpCatalog.Get(value?.ToString());
    public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture) =>
        throw new NotSupportedException();
}
